int ext4_ext_grow(struct inode *inode, handle_t *handle, unsigned int flags)
{
    struct ext4_ext_path *path = NULL;
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_super_block *sb = EXT4_SB(inode->i_sb);
    ext4_lblk_t new_block;
    int depth = ei->i_depth;
    int ret = 0;

    if (depth == 0) {
        ret = -EINVAL;
        goto out;
    }

    new_block = ext4_find_next_zero_block(inode, 0, NULL);

    if (new_block == 0) {
        ret = -ENOSPC;
        goto out;
    }

    ret = ext4_journal_get_write_access(handle, inode->i_sb, new_block, flags);
    if (ret < 0)
        goto out;

    ret = ext4_init_block(handle, inode, new_block, ei->i_file_acl, NULL);
    if (ret < 0)
        goto out;

    path = ext4_ext_find_path(inode, NULL, new_block);
    if (!path) {
        ret = -ENOMEM;
        goto out;
    }

    ret = ext4_ext_insert_index(handle, path, new_block, depth - 1);
    if (ret < 0)
        goto out;

    ei->i_max_dir_size = 0;
    inode->i_ctime = current_time(inode);
    mark_inode_dirty(inode);

out:
    if (path)
        ext4_ext_release(path);
    return ret;
}

int ext4_ext_grow(struct inode *inode, handle_t *handle, unsigned int flags)
{
    struct ext4_ext_path *path;
    struct ext4_extent *ex;
    struct ext4_extent_header *eh;
    struct ext4_extent_idx *ix;
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_sb_info *sbi = EXT4_SB(inode->i_sb);
    ext4_lblk_t new_block;
    int depth = ei->i_depth;
    int ret = 0;

    if (depth == 0) {
        ret = -EINVAL;
        goto out;
    }

    path = ext4_ext_path_alloc();
    if (!path) {
        ret = -ENOMEM;
        goto out;
    }

    new_block = ext4_find_next_zero_block(inode, 0, NULL);
    if (new_block == 0) {
        ret = -ENOSPC;
        goto out_free_path;
    }

    ret = ext4_journal_get_write_access(handle, inode->i_sb, new_block);
    if (ret < 0)
        goto out_free_path;

    ix = ext4_ext_idx(inode, path, depth);
    ex = ext4_ext_get(inode, path, depth - 1);
    eh = ext4_ext_header(inode->i_sb);

    if (ext4_ext_depth(inode) > 1) {
        ext4_set_idx(inode, ix, new_block);
        ix->ei_leaf = 0;
    } else {
        ext4_set_extent(inode, ex, new_block, 0, 0);
    }

    eh->eh_entries++;
    eh->eh_max = new_block;

    ext4_mark_inode_dirty(handle, inode);
    ext4_journal_dirty(handle, inode->i_sb, new_block);

    ext4_ext_path_free(path);
    return 0;

out_free_path:
    ext4_ext_path_free(path);
out:
    return ret;
}

int ext4_ext_grow(struct inode *inode, handle_t *handle, unsigned int flags)
{
    struct ext4_inode_info *ei = EXT4_I(inode);
    int ret = 0;
    unsigned int depth = ei->i_ext_depth;
    ext4_lblk_t goal;
    struct ext4_extent_idx *ex, *new_ex;
    struct ext4_extent_header *eh;
    struct buffer_head *bh = NULL;
    ext4_fsblk_t new_block;

    goal = (ext4_lblk_t)ei->i_ext_max;

    new_block = ext4_new_meta_block(inode, goal, &bh, flags, NULL, &ret);
    if (!new_block)
        goto out;

    ex = (struct ext4_extent_idx *)ei->i_ext_index;
    new_ex = (struct ext4_extent_idx *)bh->b_data;
    memcpy(new_ex, ex, sizeof(struct ext4_extent_idx) * ext4_ext_count(eh));

    eh = ext4_ext_header(bh->b_data);
    ext4_ext_init_header(eh, depth + 1);
    ext4_ext_index_set_count(eh, 0);
    ext4_ext_index_set_max(eh, EXT4_EXT_MAX_IDX);

    ext4_set_inode_flag(inode, EXT4_INODE_EXTENTS);

    ext4_mark_inode_dirty(handle, inode);
    brelse(bh);

out:
    return ret;
}

int ext4_ext_grow_path(handle_t *handle, struct inode *inode, unsigned int flags) {
    int ret = 0;
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_extent_header *eh;
    struct ext4_extent_idx *ex_path;
    ext4_lblk_t goal;
    struct buffer_head *bh = NULL;
    unsigned int cur_max, new_max;

    goal = ei->i_max_dir_size;
    bh = ext4_find_block(inode, goal);
    if (!bh)
        return -ENOSPC;

    ex_path = (struct ext4_extent_idx *)bh->b_data;
    cur_max = le16_to_cpu(eh->eh_max_idx);
    new_max = cur_max + 1;

    if (new_max > EXT4_MAX_INDEX) {
        ret = -ENOSPC;
        goto cleanup;
    }

    memcpy(&ex_path[new_max], &ex_path[cur_max], sizeof(struct ext4_extent_idx));
    memset(&ex_path[new_max + 1], 0, sizeof(struct ext4_extent_idx));

    eh->eh_depth = cpu_to_le16(ei->i_depth);
    eh->eh_max_idx = cpu_to_le16(new_max);

    set_buffer_uptodate(bh);
    mark_buffer_dirty(handle, bh);

    inode->i_mtime = inode->i_ctime = current_time(inode);
    mark_inode_dirty(inode);

cleanup:
    brelse(bh);
    return ret;
}

int ext4_ext_grow_inline(handle_t *handle, struct inode *inode, unsigned int flags) {
    int err = 0;
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_extent_header *eh;
    struct ext4_extent_idx *ex;
    struct buffer_head *bh = NULL;
    ext4_lblk_t new_block;
    unsigned int depth = ei->i_depth;

    new_block = ext4_get_new_block(inode, depth, flags, &err);
    if (err)
        return err;

    bh = sb_getblk(inode->i_sb, new_block);
    if (!bh) {
        err = -ENOMEM;
        goto out;
    }

    lock_buffer(bh);
    memset(bh->b_data, 0, inode->i_sb->s_blocksize);
    unlock_buffer(bh);

    eh = (struct ext4_extent_header *)bh->b_data;
    eh->eh_magic = cpu_to_le16(EXT4_EXT_MAGIC);
    eh->eh_depth = depth + 1;
    eh->eh_max = cpu_to_le16(EXT4_MAX_INDEX(inode->i_sb->s_blocksize));

    ex = (struct ext4_extent_idx *)((char *)eh + sizeof(struct ext4_extent_header));
    ex->ei_leaf = 0;
    ex->ei_leaf_offset = 0;
    ex->ei_leaf_pblk = 0;

    err = ext4_journal_get_write_access(handle, bh, flags);
    if (err)
        goto out_brelse;

    err = ext4_handle_dirty_metadata(handle, inode, bh);
    if (err)
        goto out_brelse;

    mark_inode_dirty(inode);

out_brelse:
    brelse(bh);
out:
    return err;
}
